<style>
.exec{--ink:#eaf1f8;--muted:#a3b5c8;--line:#314555;--accent:#8fe0db;color:var(--ink);background:radial-gradient(ellipse at 95% 0,#21404c66,transparent 45%),#101a24;border:1px solid var(--line);border-radius:26px;padding:clamp(18px,3vw,36px);margin-bottom:28px}.exec *{box-sizing:border-box}.exec h2,.exec h3,.exec h4{font-weight:650;letter-spacing:-.025em}.exec h2{font-size:clamp(28px,4vw,46px)}.exec h3{font-size:22px;margin-bottom:12px}.exec h4{font-size:16px}.exec p{line-height:1.55}.exec .eyebrow{font-size:11px;letter-spacing:.24em;color:var(--accent);text-transform:uppercase}.exec .muted{color:var(--muted);font-size:13px}.exec .top,.exec .between{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.exec nav{display:flex;gap:7px;overflow:auto;margin:24px 0 18px;padding-bottom:5px}.exec nav a,.exec .button,.exec button{padding:11px 16px;border:1px solid #415969;border-radius:12px;background:#1d2c39;color:var(--ink);font-size:13px;cursor:pointer;display:inline-block;white-space:nowrap}.exec nav a[aria-current=page],.exec .primary{background:linear-gradient(120deg,#d8eeed,#8dc6c4);color:#10272c;border-color:#d8eeed;font-weight:700}.exec .filters,.exec .formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px;align-items:end}.exec label{display:block;font-size:12px;color:#bed0de}.exec input,.exec select,.exec textarea{display:block;width:100%;margin-top:5px;border:1px solid #415969;border-radius:9px;padding:9px 11px;background:#101d29;color:var(--ink);font-size:13px}.exec textarea{min-height:75px}.exec input[type=checkbox]{display:inline;width:auto}.exec .panel{background:linear-gradient(135deg,#21334288,#15232e88);border:1px solid var(--line);border-radius:19px;padding:22px;margin-top:20px;min-width:0}.exec .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:18px}.exec .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px;margin-top:20px}.exec .stat{border:1px solid var(--line);background:#20324277;border-radius:15px;padding:18px}.exec .stat strong{display:block;font-size:34px;font-weight:650;margin:6px 0}.exec .badge{display:inline-block;border:1px solid #54717f;border-radius:7px;padding:3px 7px;font-size:11px;color:#c5e1e7;margin:3px 3px 3px 0}.exec .danger{color:#ffc19f;border-color:#ad6f4b;background:#58382155}.exec .good{color:#a0e7c0}.exec .scroll{overflow:auto}.exec table{width:100%;border-collapse:collapse;font-size:13px}.exec th{text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#a7bfcc;white-space:nowrap}.exec td,.exec th{padding:13px 12px;border-bottom:1px solid #304452;vertical-align:top}.exec td small{display:block;color:#a3b5c8;margin-top:5px}.exec a:hover{color:#a0e7e4}.exec details{margin-top:12px}.exec summary{cursor:pointer;padding:10px 0;font-size:13px;font-weight:600}.exec .event{display:block;background:#243b4b;border:1px solid #537382;border-left:4px solid #8fd9df;border-radius:10px;padding:12px;margin:7px 0;min-width:0;overflow-wrap:anywhere}.exec .event h4{font-size:14px}.exec .event.late{border-left-color:#f4ad7b}.exec .timeline{min-width:1000px;display:grid;grid-template-columns:190px repeat(7,minmax(110px,1fr));gap:1px;background:#354c5c;border:1px solid #354c5c;border-radius:14px;overflow:hidden}.exec .day,.exec .person{background:#172632;padding:13px;min-width:0}.exec .day.weekend{background:#13212c}.exec .day.today{box-shadow:inset 0 3px #95e2df}.exec .week-lane{grid-column:2 / span 7;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;padding:6px;background:repeating-linear-gradient(to right,#172632 0,#172632 calc(14.2857% - 1px),#354c5c calc(14.2857% - 1px),#354c5c 14.2857%);align-content:start}.exec .week-lane .event{height:auto;margin:0}.exec .calendargrid{display:grid;grid-template-columns:repeat(7,minmax(115px,1fr));gap:1px;background:#354c5c;min-width:850px}.exec .calendargrid .day{min-height:150px}.exec .bar{height:8px;background:#384958;border-radius:5px;overflow:hidden;margin:7px 0}.exec .bar span{display:block;height:100%;background:linear-gradient(90deg,#77a6bb,#93e1d5)}.exec .rowedit{border:1px solid #3e5665;border-radius:12px;padding:15px;margin:12px 0}.exec .chart{width:100%;height:270px}.exec .empty{padding:28px 0;color:var(--muted)}.exec .check{border-bottom:1px solid var(--line);padding:14px 0}.exec .report-note{padding:12px 0;color:#adc0cc;font-size:12px}.exec :focus-visible{outline:2px solid #94ded9;outline-offset:3px}@media(prefers-reduced-motion:no-preference){.exec .panel{animation:exec-arrive .35s ease-out}@keyframes exec-arrive{from{opacity:.4;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}}
</style>
